SELECT 
FROM tianquan_oauth.oauth_token
WHERE tenant_id = #{tenantId} AND authorization_pk = #{authorizationPk}
  AND token_type = #{tokenType} AND id > #{afterId} AND deleted_at IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT 
FROM tianquan_oauth.oauth_token
WHERE tenant_id = #{tenantId} AND expires_at <= #{expiresBefore}
  AND id > #{afterId} AND deleted_at IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT FROM tianquan_oauth.oauth_token WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id ASC

mapper.update:
UPDATE tianquan_oauth.oauth_token
SET consumed_at = #{po.consumedAt}, revoked_at = #{po.revokedAt},
    metadata_ciphertext = #{po.metadataCiphertext}, version = #{po.version},
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND authorization_pk = #{po.authorizationPk} AND token_digest = #{po.tokenDigest}
  AND token_type = #{po.tokenType} AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_token
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
